{
  "PROP-6a4369e9-inv-035": {
    "property_id": "PROP-6a4369e9-inv-035",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-035",
      "classification": "vulnerability",
      "code_path": "beacon-chain/sync/rpc_blob_sidecars_by_root.go::blobSidecarByRootRPCHandler::L26-109",
      "proof_trace": "Handler lacks epoch-based deprecation guard. No rejection when current_epoch >= FULU_FORK_EPOCH + MIN_EPOCHS (4096). Handler remains registered in Fulu fork map (rpc.go:52) and continues serving requests indefinitely as long as data is in retention window.",
      "attack_scenario": "After FULU_FORK_EPOCH + 4096 epochs, peers send blob_sidecars_by_root requests for recent blobs. Node serves them normally instead of rejecting, delaying PeerDAS migration and enabling resource exhaustion via legacy RPC paths.",
      "checklist_id": "PROP-6a4369e9-inv-035"
    },
    "text": "blob_sidecars_by_root must be fully deprecated after FULU_FORK_EPOCH + MIN_EPOCHS.",
    "assertion": "current_epoch >= FULU_FORK_EPOCH + MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS => respond_empty_or_reject",
    "covers": "SG-013",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

